import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"手动安装","description":"Windows、macOS 与 Linux 上安装 PostgreSQL、下载 Releases 二进制、配置三份 YAML 并开机自启。","frontmatter":{"title":"手动安装","description":"Windows、macOS 与 Linux 上安装 PostgreSQL、下载 Releases 二进制、配置三份 YAML 并开机自启。"},"headers":[],"relativePath":"guide/install/manual.md","filePath":"guide/install/manual.md","lastUpdated":1790057721000}`),a={name:`guide/install/manual.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="手动安装" tabindex="-1">手动安装 <a class="header-anchor" href="#手动安装" aria-label="Permalink to “手动安装”">​</a></h1><p>本节从「已有 PostgreSQL（可选 Redis）」走到「进程在听、浏览器能打开管理台」。官方 Releases <strong>不必</strong>再拷贝 <code>frontend/dist</code>。</p><div class="warning custom-block"><p class="custom-block-title">二进制来源</p><p>打开 <a href="https://github.com/Kirizu-Official/KiriVers/releases" target="_blank" rel="noreferrer">https://github.com/Kirizu-Official/KiriVers/releases</a>，按 <a href="/guide/install/#releases-files">选哪种安装方式</a> 中的<strong>前缀</strong>下载对应 zip（例如 <code>KiriVers-Windows-x86_64-&lt;哈希&gt;.zip</code>、<code>KiriVers-Linux-arm64-&lt;哈希&gt;.zip</code>）。解压得到 <code>kirivers-&lt;os&gt;-&lt;arch&gt;</code>（Windows 为 <code>.exe</code>）。以当前 Release 为准，不要使用猜测的直链——文件名末尾的哈希每次发版都变。</p></div><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h2><ol><li>安装 <a href="https://www.postgresql.org/download/windows/" target="_blank" rel="noreferrer">PostgreSQL Windows 安装包</a>。记住你设置的超级用户密码与端口（默认 <code>5432</code>）。创建数据库与角色，例如数据库名 <code>kirivers</code>、用户 <code>kirivers</code>。</li><li>Redis：单机可跳过，使用 <code>cache.driver=memory</code>。若需要 Redis，安装 Windows 可用的 Redis 发行或改用 Docker 只跑 Redis。</li><li>从 Releases 下载匹配的前缀（<code>KiriVers-Windows-x86_64-</code>、<code>-x86-</code> 或 <code>-arm64-</code>），解压出的 <code>.exe</code> 放到固定目录，例如 <code>C:\\KiriVers\\</code>。</li><li>将仓库 <code>configs/config-example.yaml</code>、<code>admin-example.yaml</code>、<code>client-example.yaml</code> 复制到同一目录，分别改名为 <code>config.yaml</code>、<code>admin.yaml</code>、<code>client.yaml</code>。用记事本或 VS Code 修改<strong>必须改才能启动</strong>的项： <ul><li><code>postgres.dsn</code>：主机、用户、密码、库名、端口</li><li>生产环境设置 <code>url_signing_secret</code>（否则重启后已签发下载 URL 失效） 其余键见 <a href="/guide/config/">配置</a>。</li></ul></li><li>在该目录打开终端：</li></ol><div class="language-bat line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kirivers.exe</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>无参数等价于 <code>kirivers server</code>。预期：进程保持运行；日志出现客户端 <code>:8080</code> 与管理 <code>:8081</code> 监听。</p><ol start="6"><li>浏览器打开 <code>http://127.0.0.1:8081</code>。应看到登录页（「登录 KiriVers」）。若只看到 JSON：检查 <code>admin.yaml</code> 的 <code>static_dir</code> 是否被设成空字符串（空则<strong>关闭 UI</strong>），以及是否使用了未先构建管理台的自编译占位二进制。官方 Releases 已内嵌管理台。</li></ol><details class="details custom-block"><summary>打开 :8081 只看到 JSON</summary><p><code>static_dir: &quot;&quot;</code> 会关闭 UI（即使二进制已嵌入 <code>index.html</code>）。自编译且从未在 <code>frontend/</code> 执行 <code>yarn build</code> 时，嵌入 FS 可能没有 <code>index.html</code>。官方 Releases <strong>不要</strong>再拷贝 <code>frontend/dist</code>。</p></details><ol start="7"><li>开机自启：任务计划程序 → 创建基本任务 → 触发器「计算机启动」→ 操作「启动程序」指向 <code>kirivers.exe</code>，起始于配置文件所在目录。</li></ol><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to “macOS”">​</a></h2><p>PostgreSQL：Homebrew <code>brew install postgresql@17</code> 或 <a href="https://postgresapp.com/" target="_blank" rel="noreferrer">Postgres.app</a>。可选 <code>brew install redis</code>。从 Releases 下载 <code>KiriVers-macOS-x86_64-</code>（Intel）或 <code>KiriVers-macOS-arm64-</code>（Apple Silicon），解压后复制三份 YAML，在终端运行 <code>./kirivers</code>。浏览器打开 <code>http://127.0.0.1:8081</code>。</p><h2 id="linux-未走一键脚本" tabindex="-1">Linux（未走一键脚本） <a class="header-anchor" href="#linux-未走一键脚本" aria-label="Permalink to “Linux（未走一键脚本）”">​</a></h2><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-85" id="tab-86" checked><label data-title="apt" for="tab-86">apt</label><input type="radio" name="group-85" id="tab-87"><label data-title="dnf" for="tab-87">dnf</label></div><div class="blocks"><div class="language-bash active line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql-contrib</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql-setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --initdb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></div></div><p>下载 Linux 可执行文件，复制三份 YAML，执行 <code>./kirivers</code>。</p><h3 id="systemd-示例" tabindex="-1">systemd 示例 <a class="header-anchor" href="#systemd-示例" aria-label="Permalink to “systemd 示例”">​</a></h3><p>将 <code>User</code>、<code>WorkingDirectory</code>、<code>ExecStart</code> 换成实际路径：</p><div class="language-ini line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=KiriVers</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">After</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=network.target postgresql.service</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=simple</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=kirivers</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">WorkingDirectory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/opt/kirivers</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/opt/kirivers/kirivers -config /opt/kirivers</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">Restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=on-failure</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">WantedBy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=multi-user.target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><ul><li><code>WorkingDirectory</code>：三份 YAML 所在目录（或用 <code>-config</code> 指向该目录）。</li><li><code>ExecStart</code>：二进制路径。无参数即启动双平面。</li><li><code>After=postgresql.service</code>：尽量等数据库起来；数据库在启动时必须可连，否则进程 fatal。</li></ul><p>启用：<code>sudo systemctl enable --now kirivers</code>。</p><p>下一步：<a href="/guide/config/bootstrap-admin">管理员初始化</a>。</p>`,21)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};